def is_reserved_asc_code(code):
    try:
        value=int(code);
    except (TypeError, ValueError):
        return False;
    return any(start <= value <= end for start, end in ASC_H_RESERVED_RANGES);


def asc_h_character(code, default=None):
    try:
        value=int(code);
    except (TypeError, ValueError):
        return default;
    return ASC_H_CHARACTERS.get(value, default);


def iter_asc_h_characters(start=0, end=None):
    first=max(0, int(start));
    last=ASC_H_MAX_CODE if end is None else min(ASC_H_MAX_CODE, int(end));
    for code in range(first, last + 1):
        if code in ASC_H_CHARACTERS:
            yield code, ASC_H_CHARACTERS[code];


def find_asc_h_character(text):
    wanted=str(text);
    return [code for code, value in ASC_H_CHARACTERS.items() if value == wanted];
